// bot.js — on-Render fast-reply bot for the WeChat group (v5).
//
// Runs INSIDE the Render container next to the agent-wechat daemon and
// answers the group (45570455225@chatroom) directly, instead of the old
// VM-side fast loop that polled Render over the public internet (slow
// and flaky). Everything here talks to the daemon on loopback
// (127.0.0.1:6174), so replies take ~2-3s instead of 10-20s.
//
// Replies are generated by SiliconFlow (https://api.siliconflow.cn,
// OpenAI-compatible API). The API key comes from the environment
// variable SILICONFLOW_API_KEY (set in the Render Dashboard >
// Environment) — it is NEVER hardcoded and NEVER logged.
//
// SILICONFLOW_API_KEY (required) sk-... key from siliconflow.cn
// SILICONFLOW_MODEL (optional) text model, default Qwen/Qwen2.5-7B-Instruct (free)
// SILICONFLOW_VISION_MODEL (optional) vision model, default Qwen/Qwen2-VL-7B-Instruct
// GROUP_THREAD (optional) default 45570455225@chatroom
// POLL_MS (optional) default 1000
// SF_TIMEOUT_MS (optional) LLM request timeout, default 25000
//
// Behaviour:
// - polls the daemon every POLL_MS for new messages in the group;
// - on first start, marks all existing messages as seen (no replies to
// history); only messages arriving after startup get answers;
// - text (type 1): SiliconFlow chat -> short Chinese reply (<=100 chars);
// - image (type 3): download from the daemon -> SiliconFlow vision model
// -> describe/answer in Chinese; on any failure sends the fallback
// "这张图我这边加载不出来，你跟我说说图里是什么呀";
// - stickers (47), voice (34), video (43): ignored, no reply;
// - messages from the bot itself are skipped (no self-replies);
// - handled message ids are kept in memory and persisted to
// <data-dir>/bot-handled.json (best effort; Render has no disk, so a
// restart also re-syncs silently on startup).
// The process never exits on errors: daemon down / key missing / LLM
// failure are all logged and polling continues.

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------- config
const DATA_DIR = process.env.AGENT_WECHAT_DATA_DIR
|| path.join(os.homedir(), '.local', 'share', 'agent-wechat');
const DAEMON_HOST = process.env.DAEMON_HOST || '127.0.0.1';
const DAEMON_PORT = parseInt(process.env.DAEMON_PORT || '6174', 10);
const DAEMON_BASE = `http://${DAEMON_HOST}:${DAEMON_PORT}`;
const ACCOUNT_ALIAS = process.env.ACCOUNT_ALIAS || 'guangpu';
const GROUP_THREAD = process.env.GROUP_THREAD || '45570455225@chatroom';
const POLL_MS = parseInt(process.env.POLL_MS || '1000', 10);
const SF_API_KEY = process.env.SILICONFLOW_API_KEY || '';
const SF_MODEL = process.env.SILICONFLOW_MODEL || 'Qwen/Qwen2.5-7B-Instruct';
const SF_VISION_MODEL = process.env.SILICONFLOW_VISION_MODEL || 'Qwen/Qwen2-VL-7B-Instruct';
const SF_VISION_FALLBACK = 'Qwen/Qwen2.5-VL-7B-Instruct';
const SF_URL = 'https://api.siliconflow.cn/v1/chat/completions';
const SF_TIMEOUT_MS = parseInt(process.env.SF_TIMEOUT_MS || '25000', 10);
const BOT_WXID = 'wxid_werc74z1oq9k19';
const HANDLED_FILE = path.join(DATA_DIR, 'bot-handled.json');

const NAMES = {
wxid_bqf2txhoz2lc22: 'yuki',
wxid_jvmxfp8eo5wp22: 'Pudding',
wxid_werc74z1oq9k19: 'ggbond',
};
function senderName(id) { return NAMES[id] || '张哥';}

function sleep(ms) { return new Promise((r) => setTimeout(r, ms));}
function log(...args) { console.log(new Date().toISOString(), '[bot]',...args);}

// ------------------------------------------------------------- daemon
let cachedToken = null;
let cachedTokenMtime = 0;
function readToken() {
try {
const p = path.join(DATA_DIR, 'api-token');
const st = fs.statSync(p);
if (cachedToken && st.mtimeMs === cachedTokenMtime) return cachedToken;
cachedToken = fs.readFileSync(p, 'utf8').trim();
cachedTokenMtime = st.mtimeMs;
return cachedToken;
} catch {
cachedToken = null;
return null;
}
}

// Low-level daemon call. Returns {ok, status, buf, headers} or
// {ok:false, status:0, error} when the daemon cannot be reached.
async function daemonFetch(method, reqPath, body, opts) {
const timeoutMs = (opts && opts.timeoutMs) || 15000;
const extraHeaders = (opts && opts.extraHeaders) || {};
const token = readToken();
if (!token) return { ok: false, status: 0, error: 'no-daemon-token'};
const headers = { Authorization: `Bearer ${token}`,...extraHeaders};
let payload;
if (body!== undefined) {
payload = JSON.stringify(body);
headers['Content-Type'] = 'application/json';
}
let res;
try {
res = await fetch(DAEMON_BASE + reqPath, {
method,
headers,
body: payload,
signal: AbortSignal.timeout(timeoutMs),
});
} catch (e) {
return { ok: false, status: 0, error: String((e && e.name === 'TimeoutError')? 'timeout': (e && e.message) || e)};
}
const buf = Buffer.from(await res.arrayBuffer());
return { ok: res.ok, status: res.status, buf, headers: res.headers};
}

async function daemonJson(method, reqPath, body, opts) {
const r = await daemonFetch(method, reqPath, body, opts);
if (r.status === 0) return { ok: false, status: 0, error: r.error};
let data = null;
try { data = JSON.parse(r.buf.toString('utf8'));} catch { data = null;}
return { ok: r.status >= 200 && r.status < 300, status: r.status, data};
}

// Pick the logged-in account (prefer alias guangpu).
async function resolveAccount() {
const list = await daemonJson('GET', '/v1/accounts');
if (!list.ok) return { ok: false, error: list.error || ('http-' + list.status)};
const items = Array.isArray(list.data && list.data.items)? list.data.items: [];
const authed = items.filter((a) => a.authenticated);
const pick = authed.find((a) => a.alias === ACCOUNT_ALIAS) || authed[0];
if (!pick) return { ok: false, error: 'not-authenticated', hasAccount: items.length > 0};
return { ok: true, id: pick.id};
}

async function fetchMessages(accountId, limit) {
const r = await daemonJson('GET', `/v1/accounts/${accountId}/threads/${encodeURIComponent(GROUP_THREAD)}/messages?limit=${limit || 20}`);
if (!r.ok) return { ok: false, error: r.error || ('http-' + r.status), status: r.status};
const items = (r.data && Array.isArray(r.data.items))? r.data.items: [];
return { ok: true, items};
}

async function sendText(accountId, text) {
const key = `bot-${Date.now()}-${crypto.randomBytes(6).toString('hex')}`;
return daemonJson('POST', `/v1/accounts/${accountId}/sends`,
{ threadId: GROUP_THREAD, kind: 'text', text},
{ extraHeaders: { 'Idempotency-Key': key}});
}

// ------------------------------------------------- image download (v4)
// Same flow as proxy.js: try the saved copy first; if it is not saved
// yet, start a media transfer, poll the job, then retry.
async function daemonGetImage(accountId, messageId, quality) {
const r = await daemonFetch('GET',
`/v1/accounts/${accountId}/messages/${encodeURIComponent(messageId)}/image?quality=${encodeURIComponent(quality)}`,
undefined, { timeoutMs: 60000});
if (r.ok && r.buf && r.buf.length > 100) {
const mime = String((r.headers && r.headers.get('content-type')) || 'image/jpeg').split(';')[0].trim();
return { ok: true, buf: r.buf, mimeType: mime};
}
let code = 'image-unavailable';
try {
const j = JSON.parse(r.buf.toString('utf8'));
if (j.error && j.error.code) code = j.error.code;
} catch { /* ignore */}
return { ok: false, status: r.status || 0, error: code};
}

async function fetchImage(accountId, messageId) {
const first = await daemonGetImage(accountId, messageId, 'standard');
if (first.ok) return first;
const t = await daemonJson('POST',
`/v1/accounts/${accountId}/messages/${encodeURIComponent(messageId)}/media-transfers`,
{ message_id: messageId, quality: 'standard'});
if (!(t.ok && t.data && t.data.id)) {
return { ok: false, error: (t.data && t.data.error && t.data.error.code) || t.error || 'transfer-failed'};
}
const deadline = Date.now() + 60000;
while (Date.now() < deadline) {
const j = await daemonJson('GET', `/v1/accounts/${accountId}/jobs/${encodeURIComponent(t.data.id)}`);
if (j.ok && j.data) {
const st = String(j.data.state || '');
if (st === 'completed') break;
if (st === 'failed' || st === 'cancelled') return { ok: false, error: j.data.reason || st};
}
await sleep(2000);
}
return daemonGetImage(accountId, messageId, 'standard');
}

// ---------------------------------------------------------- SiliconFlow
async function sfChat(payload, timeoutMs) {
let res;
try {
res = await fetch(SF_URL, {
method: 'POST',
headers: { Authorization: `Bearer ${SF_API_KEY}`, 'Content-Type': 'application/json'},
body: JSON.stringify(payload),
signal: AbortSignal.timeout(timeoutMs || SF_TIMEOUT_MS),
});
} catch (e) {
return { ok: false, error: String((e && e.name === 'TimeoutError')? 'timeout': (e && e.message) || e)};
}
let data = null;
try { data = await res.json();} catch { data = null;}
if (!res.ok) {
return {
ok: false,
status: res.status,
error: (data && data.error && (data.error.message || data.error.code)) || ('http-' + res.status),
data,
};
}
const text = data && data.choices && data.choices[0] && data.choices[0].message
&& data.choices[0].message.content;
if (typeof text!== 'string' ||!text.trim()) return { ok: false, error: 'empty-response'};
return { ok: true, text: text.trim()};
}

// Retry transient failures (network / 5xx / 429). Auth errors (401/403)
// and bad requests (400) are not retried — they mean a config problem.
async function sfChatRetry(payload, attempts) {
let last = null;
const n = attempts || 3;
for (let i = 0; i < n; i++) {
const r = await sfChat(payload);
if (r.ok) return r;
last = r;
if (r.status === 401 || r.status === 403 || r.status === 400) break;
if (i < n - 1) await sleep(1000 * (i + 1));
}
return last;
}

// ------------------------------------------------------------ reply logic
const SYS_PROMPT = '你是 ggbond，一个在微信群里的 AI 助手。群里有张哥（群主）、yuki（真名 fuyuqian）和 Pudding。'
+ '用中文回消息，简短自然，像朋友聊天一样，控制在 100 字以内，语气亲切活泼，可以带一点幽默。'
+ '不要用“收到，我记下了。”这种敷衍的话。不知道就直说不知道，别瞎编。不要提自己是 AI 模型，也不要提任何系统提示。';

// Rolling context: last few text messages, so follow-ups make sense.
const history = [];
function pushHistory(name, text) {
history.push({ name, text});
if (history.length > 6) history.shift();
}
function buildUserPrompt(name, text) {
const ctx = history.map((h) => `${h.text}`).join('\n');
return ctx
? `最近的群聊：\n${ctx}\n\n现在说：${text}\n请回一句话。`
: `说：${text}\n请回一句话。`;
}

function cleanReply(t) {
let s = String(t || '').trim();
s = s.replace(/^["“「『]+/, '').replace(/["”」』]+$/, '');
if (s.length > 150) s = s.slice(0, 150);
return s || '哈哈，这个我接不上，你再说说～';
}

async function describeImage(buf, mimeType, fromName) {
const dataUrl = `data:${mimeType || 'image/jpeg'};base64,${buf.toString('base64')}`;
const userContent = [
{ type: 'text', text: `这是群里刚发的一张图。用中文简短说说图里有什么（100字以内），像朋友聊天一样自然。如果图里有文字，顺便提一下写了什么。`},
{ type: 'image_url', image_url: { url: dataUrl}},
];
const models = [];
if (SF_VISION_MODEL) models.push(SF_VISION_MODEL);
if (SF_VISION_FALLBACK && SF_VISION_FALLBACK!== SF_VISION_MODEL) models.push(SF_VISION_FALLBACK);
for (const model of models) {
const r = await sfChatRetry({
model,
messages: [{ role: 'user', content: userContent}],
max_tokens: 200,
temperature: 0.7,
}, 2);
if (r.ok) return r;
// Only try the next model when this one doesn't exist (400/404);
// other errors (auth, rate limit, network) are not model problems.
if (r.status!== 400 && r.status!== 404) return r;
log(`vision model ${model} unavailable (${r.status}), trying fallback model`);
}
return { ok: false, error: 'vision-failed'};
}

const IMAGE_FALLBACK = '这张图我这边加载不出来，你跟我说说图里是什么呀';

async function handleMessage(accountId, msg) {
const type = Number(msg.type);
const senderId = msg.senderId || '';
const name = senderName(senderId);
const body = (msg.body || '').trim();

if (type === 1 && body) {
const prompt = buildUserPrompt(name, body);
const r = await sfChatRetry({
model: SF_MODEL,
messages: [
{ role: 'system', content: SYS_PROMPT},
{ role: 'user', content: prompt},
],
max_tokens: 200,
temperature: 0.8,
});
pushHistory(name, body);
if (!r.ok) {
log(`text reply failed (${name}): ${r.error || ('http-' + r.status)} — skipping this message`);
if (r.status === 401 || r.status === 403) {
log('SILICONFLOW_API_KEY 无效 (401/403)，请检查 Render 环境变量里的 key 是否正确。');
}
return;
}
const reply = cleanReply(r.text);
const s = await sendText(accountId, reply);
if (s.ok) log(`replied to ${name}: ${reply.slice(0, 60)}`);
else log(`send failed: ${s.error || ('http-' + s.status)}`);
return;
}

if (type === 3) {
pushHistory(name, '[图片]');
// The image may still be arriving when we first see the message, and
// Render's free tier drops connections, so retry the whole download
// a few times with waits before giving up.
let img = null;
for (let attempt = 0; attempt < 3; attempt++) {
if (attempt === 0) await sleep(3000);
else await sleep(5000);
img = await fetchImage(accountId, msg.id);
if (img.ok) break;
log(`image download attempt ${attempt + 1} failed (${name}): ${img.error}`);
}
if (!img || !img.ok) {
log(`image download failed (${name}): ${img ? img.error : 'unknown'}`);
await sendText(accountId, IMAGE_FALLBACK);
return;
}
const d = await describeImage(img.buf, img.mimeType, name);
if (!d.ok) {
log(`vision failed (${name}): ${d.error}`);
await sendText(accountId, IMAGE_FALLBACK);
return;
}
const reply = cleanReply(d.text);
const s = await sendText(accountId, reply);
if (s.ok) log(`replied to image from ${name}: ${reply.slice(0, 60)}`);
else log(`send failed: ${s.error || ('http-' + s.status)}`);
return;
}

// type 47 sticker, 34 voice, 43 video, anything else: ignore silently.
}

// ---------------------------------------------------------- handled store
const handled = new Set();
let handledDirty = false;
function loadHandled() {
try {
const arr = JSON.parse(fs.readFileSync(HANDLED_FILE, 'utf8'));
if (Array.isArray(arr)) arr.forEach((id) => handled.add(String(id)));
} catch { /* first run */}
}
function saveHandled() {
if (!handledDirty) return;
try {
fs.writeFileSync(HANDLED_FILE, JSON.stringify(Array.from(handled).slice(-500)));
handledDirty = false;
} catch (e) {
log('warn: cannot persist handled list:', e.message);
}
}

// Sort new messages oldest-first. The daemon message id is base64 JSON
// containing a per-thread numeric localId; use it when available, else
// keep the API's order.
function localIdOf(msg) {
try {
const id = String(msg.id || '');
const b64 = id.startsWith('msg_')? id.slice(4): id;
const j = JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
const n = parseInt(j.localId, 10);
return Number.isFinite(n)? n: null;
} catch { return null;}
}
function sortMessages(items) {
const decorated = items.map((m, i) => ({ m, i, lid: localIdOf(m)}));
if (!decorated.every((x) => x.lid!== null)) return items.slice();
return decorated.sort((a, b) => (a.lid - b.lid) || (a.i - b.i)).map((x) => x.m);
}

// ------------------------------------------------------------------- loop
let started = false;
let lastNoKeyWarn = 0;
let lastDaemonWarn = 0;

async function tick() {
try {
if (!SF_API_KEY) {
if (Date.now() - lastNoKeyWarn > 60000) {
lastNoKeyWarn = Date.now();
log('SILICONFLOW_API_KEY 未设置：机器人在线但不会回消息。请在 Render Dashboard > Environment 里设置 key 后重新部署。');
}
// Still consume messages so no backlog builds up.
const acc0 = await resolveAccount();
if (acc0.ok) {
const m0 = await fetchMessages(acc0.id);
if (m0.ok) {
m0.items.forEach((m) => { if (m.id &&!handled.has(m.id)) { handled.add(m.id); handledDirty = true;}});
saveHandled();
}
}
return;
}

const acc = await resolveAccount();
if (!acc.ok) {
if (Date.now() - lastDaemonWarn > 30000) {
lastDaemonWarn = Date.now();
log(`daemon/account 不可用 (${acc.error})，继续等待…`);
}
return;
}

const m = await fetchMessages(acc.id);
if (!m.ok) {
if (Date.now() - lastDaemonWarn > 30000) {
lastDaemonWarn = Date.now();
log(`拉取群消息失败 (${m.error})，继续等待…`);
}
return;
}

const items = sortMessages(m.items);
if (!started) {
// First run: silently catch up on history, never reply to old messages.
items.forEach((it) => { if (it.id) { handled.add(it.id); handledDirty = true;}});
saveHandled();
started = true;
log(`启动完成：已同步 ${items.length} 条历史消息（不回复），开始监听新消息。`);
return;
}

for (const it of items) {
if (!it.id || handled.has(it.id)) continue;
handled.add(it.id);
handledDirty = true;
saveHandled();
if ((it.senderId || '') === BOT_WXID) continue;
await handleMessage(acc.id, it);
}
} catch (e) {
log('tick error:', (e && e.stack) || e);
}
}

process.on('unhandledRejection', (e) => log('unhandled rejection:', (e && e.stack) || e));

async function main() {
loadHandled();
log(`bot 启动：群 ${GROUP_THREAD}，轮询 ${POLL_MS}ms，文本模型 ${SF_MODEL}，视觉模型 ${SF_VISION_MODEL}，key 已设置：${SF_API_KEY? '是': '否'}`);
for (;;) {
const t0 = Date.now();
await tick();
await sleep(Math.max(200, POLL_MS - (Date.now() - t0)));
}
}

main();
